// Passe avant d'un neurone : somme pondérée + biais, puis activation.
// TODO : ceci oublie le BIAIS et ignore l'activation — un neurone est
//        activation(Σ inputs·weights + bias).
export function forward(inputs, weights, bias, activation) {
  let z = 0;
  for (let i = 0; i < inputs.length; i++) z += inputs[i] * weights[i];
  return z;
}

